def f(g):
    H,W=len(g),len(g[0])
    bars=[i for i in range(H) if all(x==2 for x in g[i])]
    bar=bars[0] if bars else None
    out=[[0]*W for _ in range(H)]
    comps=components(g)
    # direction: bar at top -> grow down from bar+1; bar at bottom -> grow up to bar-1
    down = bar is not None and bar==0
    base = bar+1 if down else bar-1
    # per-column component analysis
    colcomps={}
    for cc in comps:
        for r,c in cc:
            colcomps.setdefault(c,[]).append(cc)
    # dedupe per column: unique comps
    for c in colcomps:
        colcomps[c]=list({id(x):None for x in colcomps[c]}).keys()
    placed=[]  # (col, top) per col, keyed by col
    def next_bottom(col, h):
        t = placed.get(col)
        if t is None: return base - h  # flush against bar
        return t - h   # just below previous
    for c,cc in colcomps.items():
        cs=sorted(cc,key=lambda cc:max(r for r,_ in cc))  # bottom asc
        # place bottom-up: highest-bottom first flush, others just below
        order=sorted(cs,key=lambda cc:-max(r for r,_ in cc))
        for i,cc in enumerate(order):
            rs=[r for r,_ in cc]; h=max(rs)-min(rs)+1
            nb=next_bottom(c,h)
            tp=nb-h+1
            placed[c]=tp-h  # store next available top for following comps in this col (actually stored as top of previous comp)
            # wait: for next comp in same col, bottom = tp-1 => its top = tp-1-h+1 = tp-h
            placed[c]=tp-h
            for r,kk in zip(sorted(set(rs)),range(h)):
                out[tp+kk][c]=g[min(rs)+kk][c] if False else None
    # redo placement cleanly
    out=[[0]*W for _ in range(H)]
    placed={}
    order_sorted=sorted(comps,key=lambda cc:-max(r for r,_ in cc))
    for cc in order_sorted:
        rs=[r for r,_ in cc]; cs=[c for _,c in cc]
        h=max(rs)-min(rs)+1
        cols_set=set(cs)
        # determine target column(s): use min col
        c=min(cols_set)
        nb=placed.get(c)
        if nb is None: tb=base-h      # flush
        else:           tb=nb          # just below previous comp in this col (previous comp's top)
        tp=tb-h+1
        placed[c]=tp
        for r,cv in cc:
            nr=tp+(r-min(rs))
            out[nr][cv]=g[r][cv]
    for r in bars:
        out[r]=[2]*W
    return out

