# Demo: all rows of wall (color 2) preserved. Non-wall nonzero cells in each row: run-length encoded, then compacted as one contiguous block adjacent to wall column (col W-1), preserving run order & total length.
def f(g):
    H,W=len(g),len(g[0])
    # wall color = full single-color non-zero column or row
    wall=None
    for c in range(W):
        if len(set(g[r][c] for r in range(H)))==1 and g[0][c]!=0: wall=g[0][c]; anchor=c; break
    if wall is None:
        for r in range(H):
            if len(set(g[r]))==1 and g[r][0]!=0: wall=g[r][0]; anchor=r; break
    out=[[0]*W for _ in range(H)]
    for r in range(H):
        runs=[]; c=0
        while c<W:
            v=g[r][c]
            if v!=0 and v!=wall:
                s=c
                while c<W and g[r][c]==v: c+=1
                runs.append((s,c-s,v))
            else:
                c+=1
        tot=sum(l for _,l,_ in runs)
        end=W-1           # block ends right before the wall col
        cur=end-tot+1     # start index
        for _,l,v in runs:
            for k in range(l): out[r][cur+k]=v
        # clear original object positions not overwritten? we rebuild out so fine
    return out
